import pulp

# Define data
stations = ['A', 'B', 'C']
locations = ['D', 'E', 'F', 'G']
urgency = {'D': 4, 'E': 3, 'F': 2, 'G': 1}
time_dict = {
    'A': {'D': 15, 'E': 20, 'F': 25, 'G': 30},
    'B': {'D': 20, 'E': 15, 'F': 30, 'G': 25},
    'C': {'D': 25, 'E': 30, 'F': 15, 'G': 20}
}
ambulances = {'A': 2, 'B': 3, 'C': 1}

# Create problem
prob = pulp.LpProblem("RescueDispatch", pulp.LpMinimize)

# Define variables
variables = {}
for s in stations:
    for l in locations:
        var = pulp.LpVariable(f"x_{s}_{l}", cat='Binary')
        variables[(s, l)] = var

# Objective function
prob += sum((urgency[l] + 0.1 * time_dict[s][l]) * variables[(s, l)] for s in stations for l in locations)

# Constraints
for l in locations:
    prob += pulp.lpSum(variables[(s, l)] for s in stations) == 1

for s in stations:
    prob += pulp.lpSum(variables[(s, l)] for l in locations) <= ambulances[s]

# Solve
prob.solve(pulp.PULP_CBC_CMD(msg=0))

# Output
print(f"Answer: {pulp.value(prob.objective)}")
